\documentclass{article}
\usepackage{amsmath}
\begin{document}
\section{Model}
The replica free energy is
\begin{equation*}
f = -\frac{1}{\beta N} \ln Z .
\end{equation*}
In the thermodynamic limit the overlap satisfies
\begin{equation*}
q = \frac{1}{N} \sum_i s_i^{(1)} s_i^{(2)} .
\end{equation*}
\end{document}

